using Ordering.Legacy;

namespace Ordering;

/// <summary>Produces dispatch labels for an order.</summary>
public sealed class LabelPrinter
{
    public string Print(Order order, string service)
    {
        // TODO: support multi-parcel orders with one label per parcel
        return LabelApiV2.Render(new LabelRequest
        {
            Reference = order.Reference,
            Service = service
        });
    }
}
